from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak, KeepTogether, Flowable

OUT = Path('output/pdf/2136_revised_version.pdf')
OUT.parent.mkdir(parents=True, exist_ok=True)

S = getSampleStyleSheet()
S.add(ParagraphStyle(name='PaperTitle', parent=S['Title'], fontName='Helvetica-Bold', fontSize=16, leading=19, alignment=TA_CENTER, spaceAfter=6))
S.add(ParagraphStyle(name='Authors', parent=S['Normal'], fontSize=9.2, leading=12, alignment=TA_CENTER, spaceAfter=10))
S.add(ParagraphStyle(name='Abs', parent=S['BodyText'], fontSize=9.15, leading=12.4, borderColor=colors.HexColor('#aab7c4'), borderWidth=.45, borderPadding=6, spaceAfter=8))
S.add(ParagraphStyle(name='H1x', parent=S['Heading1'], fontName='Helvetica-Bold', fontSize=11.7, leading=14, textColor=colors.HexColor('#163a5f'), spaceBefore=9, spaceAfter=3))
S.add(ParagraphStyle(name='H2x', parent=S['Heading2'], fontName='Helvetica-Bold', fontSize=10, leading=12, textColor=colors.HexColor('#163a5f'), spaceBefore=6, spaceAfter=2))
S.add(ParagraphStyle(name='Bodyx', parent=S['BodyText'], fontSize=9.05, leading=12.25, spaceAfter=4.3))
S.add(ParagraphStyle(name='Cap', parent=S['BodyText'], fontSize=8.25, leading=10.3, alignment=TA_CENTER, textColor=colors.HexColor('#374151'), spaceBefore=2, spaceAfter=6))
