S.add(ParagraphStyle(name='Quote', parent=S['BodyText'], fontName='Helvetica-Oblique', fontSize=8.7, leading=11.5, leftIndent=8, textColor=colors.HexColor('#374151'), spaceAfter=2))

def p(t, style='Bodyx'): return Paragraph(t, S[style])

def table(data, widths, header=True):
    t = Table(data, colWidths=widths, repeatRows=1 if header else 0, hAlign='CENTER')
    st=[('GRID',(0,0),(-1,-1),.35,colors.HexColor('#cbd5e1')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),4),('RIGHTPADDING',(0,0),(-1,-1),4),('TOPPADDING',(0,0),(-1,-1),3.5),('BOTTOMPADDING',(0,0),(-1,-1),3.5)]
    if header: st += [('BACKGROUND',(0,0),(-1,0),colors.HexColor('#dbeafe')),('FONTNAME',(0,0),(-1,0),'Helvetica-Bold')]
    t.setStyle(TableStyle(st)); return t

class Framework(Flowable):
    def __init__(self): super().__init__(); self.width=165*mm; self.height=48*mm
    def draw(self):
        c=self.canv; w=self.width; h=self.height
        c.setFont('Helvetica-Bold',8); c.setFillColor(colors.HexColor('#163a5f'))
        c.drawString(0,h-6*mm,'Completed evaluation')
        c.drawString(92*mm,h-6*mm,'Proposed extension')
        boxes=[(0,27,'Public text corpus','TF-IDF / soft voting'),(44,27,'Indian gold set','Human-labelled evaluation'),(92,27,'Paired screenshot + text','Data collection'),(132,27,'Text + visual encoders','Late fusion')]
        for x,y,a,b in boxes:
            c.setFillColor(colors.HexColor('#eff6ff') if x<92 else colors.HexColor('#fef3c7')); c.setStrokeColor(colors.HexColor('#64748b')); c.roundRect(x*mm,y*mm,32*mm,13*mm,2*mm,fill=1,stroke=1)
            c.setFillColor(colors.black); c.setFont('Helvetica-Bold',6.8); c.drawCentredString((x+16)*mm,(y+8)*mm,a); c.setFont('Helvetica',6.5); c.drawCentredString((x+16)*mm,(y+4)*mm,b)
        for x in [33,77,121]:
            c.setStrokeColor(colors.HexColor('#475569')); c.line(x*mm,33.5*mm,(x+10)*mm,33.5*mm); c.line((x+10)*mm,33.5*mm,(x+8)*mm,35*mm); c.line((x+10)*mm,33.5*mm,(x+8)*mm,32*mm)
        c.setFillColor(colors.HexColor('#e0f2fe')); c.roundRect(44*mm,7*mm,40*mm,12*mm,2*mm,fill=1,stroke=1); c.setFillColor(colors.black); c.setFont('Helvetica-Bold',7); c.drawCentredString(64*mm,14*mm,'Binary / category output'); c.setFont('Helvetica',6.5); c.drawCentredString(64*mm,10*mm,'with retained text evidence')
        c.setFillColor(colors.HexColor('#dcfce7')); c.roundRect(111*mm,7*mm,40*mm,12*mm,2*mm,fill=1,stroke=1); c.setFillColor(colors.black); c.setFont('Helvetica-Bold',7); c.drawCentredString(131*mm,14*mm,'CCPA interpretation'); c.setFont('Helvetica',6.5); c.drawCentredString(131*mm,10*mm,'future validation required')
        c.setStrokeColor(colors.HexColor('#475569')); c.line(64*mm,27*mm,64*mm,19*mm); c.line(64*mm,19*mm,64*mm,19*mm); c.line(131*mm,27*mm,131*mm,19*mm)

def footer(c, doc):
    c.saveState(); c.setStrokeColor(colors.HexColor('#d1d5db')); c.line(17*mm,14*mm,193*mm,14*mm); c.setFont('Helvetica',7.5); c.setFillColor(colors.HexColor('#64748b')); c.drawString(17*mm,9.3*mm,'Paper ID 2136 - Revised manuscript'); c.drawRightString(193*mm,9.3*mm,f'{doc.page}'); c.restoreState()

doc=SimpleDocTemplate(str(OUT), pagesize=A4, leftMargin=17*mm,rightMargin=17*mm,topMargin=15*mm,bottomMargin=19*mm)
story=[]
story += [p('AI-Based Detection and Analysis of Dark Patterns', 'PaperTitle'),p('A Human-Validated India-Focused Text Baseline with a CCPA-Aware Evaluation Framework','PaperTitle'),p('Siraj Kanungo, Rohin A. Hegde, Md Shere Habib, K. Avinash Reddy, Mohammad Sirajuddin<br/>School of Computer Science and Engineering, VIT-AP University, Amaravati, Andhra Pradesh, India','Authors')]
story += [p('<b>Abstract.</b> Dark patterns are deceptive interface practices that steer users toward outcomes that benefit the platform. We evaluate an India-focused text detector against an independently held-out gold set of 499 human-labelled Indian interface snippets, of which 26 are dark patterns. The gold set is never used for training. A soft-voting text model achieves an estimated pool-weighted F1 of 0.171 (95% bootstrap range: 0.034-0.493), compared with 0.056 (0.019-0.109) for a pseudo-labeller baseline, and outperforms the baseline in 95% of paired resamples. At a 0.50 threshold, the model produces 11 false alarms, versus 155 for the baseline, but detects only 9 of 26 dark rows. The large gap from an in-distribution F1 of 0.927 to the human-labelled Indian evaluation demonstrates the importance of domain-specific validation. We provide category results, a CCPA category crosswalk, error analysis, and ethical limitations. Multimodal fusion and transformer comparisons remain future work; no performance claims are made for either.', 'Abs'),p('<b>Keywords:</b> dark patterns; deceptive design; human evaluation; CCPA; Indian e-commerce; domain shift; machine learning','Bodyx')]

story += [p('1. Introduction','H1x'),p('Dark patterns use interface wording, layout, or interaction flow to influence users in ways that primarily benefit the platform. Examples include false urgency, basket sneaking, confirm shaming, and subscription traps. India\'s Central Consumer Protection Authority (CCPA) published the Guidelines for Prevention and Regulation of Dark Patterns in 2023, creating a practical need for evidence-based identification of such practices [5].'),p('Automated dark-pattern research has used text, visual signals, DOM structure, and mobile-app exploration [1-4]. However, strong scores on benchmark corpora may not transfer to Indian user interfaces or to naturally imbalanced, human-labelled data. This revision therefore narrows the completed contribution to a transparent text evaluation and makes the main empirical result the measured domain gap. The previously proposed multimodal framework is retained only as a future research design.')]
story += [p('Contributions','H2x'),p('(1) We evaluate a text detector on a held-out, human-labelled Indian gold set of 499 snippets; (2) we compare it with a pseudo-labeller baseline using pool-weighted estimates and paired bootstrap resampling; (3) we report category performance, error patterns, and a CCPA crosswalk; and (4) we document constraints that prevent legal or multimodal claims.')]

story += [p('2. Related Work','H1x'),p('Bajaj et al. [1] combine structural, visual, and textual signals; AidUI [2] localizes UI patterns with computer vision and NLP; UIGuard [3] uses knowledge-driven checking for mobile UIs; and AppRay [4] explores dynamic app states. These systems motivate multimodal research, but their task definitions, platforms, and datasets differ from the present text-only evaluation. Mathur et al. [6] established web-scale evidence of dark patterns, while Yada et al. [7] released a text dataset and baseline evaluations. Our result is not a claim of a superior universal detector; it measures how a model trained with available data behaves on held-out Indian text.')]

story += [p('3. Data, Labels, and CCPA Crosswalk','H1x'),p('The in-distribution training corpus includes public ec-darkpattern text records derived from the dataset of Yada et al. [7], itself based on dark-pattern texts reported by Mathur et al. [6] with additional non-dark-pattern text from the same e-commerce sites. The original benchmark contains 2,356 samples: 1,178 dark-pattern and 1,178 non-dark-pattern texts. Each record contains an identifier, interface text, binary label, and fine-grained category. The 50/50 class balance is suitable for controlled benchmarking but is not representative of real deployment prevalence.'),p('The external gold set contains 499 Indian snippets manually labelled during collection and is held out from training and model selection. Twenty-six rows are marked as dark patterns. To estimate performance across the roughly 26,000 scraped snippets represented by the sampling design, each gold row is weighted by the number of snippets it represents. Because dark examples are rare, the 95% bootstrap ranges are wide and small differences should not be overinterpreted.'),p('Annotation limitation. The current gold labels were produced by a single annotator. Consequently, this revision cannot report inter-annotator agreement. Before a future release or legal-facing deployment, an independently double-labelled subset, a written codebook, and agreement statistics (Cohen\'s kappa or Krippendorff\'s alpha) are required.' )]
ccpa=[ [p('<b>Pattern family</b>','Small'),p('<b>CCPA interpretation</b>','Small'),p('<b>Retained evidence</b>','Small')], [p('Urgency / Scarcity','Small'),p('False Urgency','Small'),p('Text span, timer or stock phrase','Small')], [p('Social Proof','Small'),p('False or misleading popularity claim','Small'),p('Popularity claim and surrounding context','Small')], [p('Misdirection','Small'),p('Confirm Shaming, Interface Interference, or Trick Question','Small'),p('Exact wording and UI context','Small')], [p('Obstruction','Small'),p('Subscription Trap','Small'),p('Cancellation-flow text','Small')], [p('Sneaking','Small'),p('Basket Sneaking or Drip Pricing','Small'),p('Checkout text and price disclosure','Small')], [p('Forced Action','Small'),p('Forced Action','Small'),p('Required action or disclosure','Small')]]
story += [table(ccpa,[43*mm,61*mm,62*mm]),p('Table 1. CCPA-oriented interpretation crosswalk. This is an analytic mapping, not a legal finding.','Cap')]

story += [p('4. Methods','H1x'),p('The completed detector uses word and character n-gram TF-IDF features with a soft-voting ensemble of LightGBM, support-vector, and logistic-regression classifiers for binary detection. Model selection uses cross-validation on the training data only. A separate logistic-regression classifier predicts a reduced category label set; rare Sneaking and Forced Action samples are merged into Other because their available support is too small for stable standalone estimates.'),p('Figure 1 separates completed work from the planned multimodal extension. The screenshot branch, fusion mechanism, and CCPA category validation have not been implemented or evaluated in this study. Likewise, transformer models were not trained for this revision and are not used as a comparison basis.')]
story += [Framework(),p('Figure 1. Completed text evaluation (blue) and proposed multimodal extension (amber). The proposed components are not reported as experimental results.','Cap')]

story += [p('5. Experimental Protocol','H1x'),p('In-distribution results use a stratified held-out 20% split of the training corpus. External evaluation uses the 499-row Indian gold set only once after model selection. We report pool-weighted precision, recall, and F1, plus row-level counts to make the impact of the sampling design visible. Uncertainty is estimated through paired bootstrap resampling of the gold evaluation. The baseline is a pseudo-labeller, not a supervised model trained against the gold labels.')]
rows=[[p('<b>System</b>','Small'),p('<b>Precision</b>','Small'),p('<b>Recall</b>','Small'),p('<b>F1 [95% range]</b>','Small'),p('<b>Caught</b>','Small'),p('<b>False alarms</b>','Small')],[p('Soft voting, threshold 0.50','Small'),p('0.410','Small'),p('0.108','Small'),p('0.171 [0.034-0.493]','Small'),p('9/26','Small'),p('11','Small')],[p('Soft voting, CV-tuned 0.18','Small'),p('0.113','Small'),p('0.159','Small'),p('0.132 [0.046-0.260]','Small'),p('16/26','Small'),p('75','Small')],[p('Pseudo-labeller baseline','Small'),p('0.032','Small'),p('0.238','Small'),p('0.056 [0.019-0.109]','Small'),p('12/26','Small'),p('155','Small')]]
story += [table(rows,[45*mm,22*mm,22*mm,42*mm,20*mm,25*mm]),p('Table 2. Pool-weighted external evaluation on the held-out Indian gold set (n = 499; 26 dark rows).','Cap')]

story += [p('6. Results and Discussion','H1x'),p('The main result is an improvement over the pseudo-labeller baseline at the default threshold: estimated F1 rises from 0.056 to 0.171, a +0.115 difference (95% range: -0.012 to +0.432), and the model has higher F1 in 95% of paired resamples. The gain is driven primarily by precision: false alarms fall from 155 to 11. The trade-off is low recall. At the 0.50 threshold, the model identifies 9 of 26 dark rows; lowering the threshold identifies 16 but creates 75 false alarms. These results are too uncertain to support claims of small improvements, but they clearly show that in-distribution performance does not establish Indian deployment performance.'),p('On the in-distribution held-out split, soft voting obtains cross-validation F1 = 0.913, test F1 = 0.927, and accuracy = 0.966. The category model obtains test F1 = 0.956 and accuracy = 0.955 (macro-F1 = 0.90); such results reflect the benchmark distribution, not the gold set. On the 26 dark gold rows, the category model achieves 0.62 accuracy and macro-F1 = 0.57, a far more tentative estimate due to small support.')]
cat=[[p('<b>Evaluation</b>','Small'),p('<b>F1 / macro-F1</b>','Small'),p('<b>Accuracy</b>','Small'),p('<b>Interpretation</b>','Small')],[p('Binary, benchmark split','Small'),p('0.927','Small'),p('0.966','Small'),p('In-distribution only','Small')],[p('Category, benchmark split','Small'),p('0.90 macro','Small'),p('0.955','Small'),p('Rare labels merged','Small')],[p('Binary, Indian gold','Small'),p('0.171 weighted','Small'),p('Not prevalence-informative','Small'),p('External, low-prevalence evaluation','Small')],[p('Category, 26 gold dark rows','Small'),p('0.57 macro','Small'),p('0.62','Small'),p('Exploratory; very small support','Small')]]
story += [table(cat,[43*mm,35*mm,34*mm,64*mm]),p('Table 3. In-distribution and external results must not be compared as if they were the same task.','Cap')]
story += [p('Error analysis','H2x'),p('Most remaining false negatives involve subtle or contextual claims that are lexically unlike benchmark examples, such as “Trusted by 20+ million customers.” The model also misses novel numeric urgency strings. False positives are substantially reduced but remain possible when neutral inventory or promotional language resembles scarcity. The observed external domain gap indicates that lexical overlap is insufficient to establish deceptive intent; surrounding UI context and independent human review remain necessary.')]

story += [p('7. Ethics, Legal Scope, and Data Availability','H1x'),p('Collection should be limited to public interface content, rate limited, and designed to minimize capture of personal data. Screenshots and text should be redacted where they contain identifiers. Predictions may cause harm if they wrongly label a legitimate business practice as deceptive; outputs must therefore retain evidence and be reviewed by a human. The CCPA mapping is a research-oriented interpretation of guideline categories, not legal advice, an enforcement finding, or a determination of liability.'),p('We intend to release permissible de-identified annotations, label definitions, model code, split identifiers, and the CCPA crosswalk. Raw screenshots or text that cannot be redistributed because of platform terms, copyright, privacy, or security concerns will not be released; reproducible collection instructions and derived annotations should be provided instead.')]

story += [p('8. Limitations and Future Work','H1x'),p('This work does not yet include a transformer baseline, a fully implemented screenshot branch, multimodal fusion, or site-disjoint cross-site testing. The gold data has a small number of positive cases and was singly annotated. The reported confidence ranges are consequently broad. Future work should create a double-annotated, site-disjoint Indian dataset; compare transformers and visual models under the same protocol; validate CCPA assignments; and evaluate calibrated human-in-the-loop operating points.')]
story += [p('9. Conclusion','H1x'),p('A strong benchmark score does not transfer automatically to real Indian interface text. Although the model improves pool-weighted F1 over the pseudo-labeller baseline and sharply reduces false alarms, it still misses most dark examples. The appropriate conclusion is not that dark-pattern detection is solved, but that human-labelled, domain-specific evaluation exposes limitations masked by balanced benchmark splits. The proposed multimodal and CCPA-aware system remains a testable next step, not a completed result.')]

story += [p('References','H1x'),p('[1] A. Bajaj et al., “A Complete Analysis for Dark Pattern Detection Using Structural, Visual and Textual Information,” IJCISIM, 17, 14-25, 2025. [2] S. M. H. Mansur et al., “AidUI,” ICSE, 1958-1970, 2023. [3] J. Chen et al., “Unveiling the Tricks: Automatic Detection of Dark Patterns in Mobile Applications,” UIST, 2023. [4] J. Chen et al., “From Exploration to Revelation: Detecting Dark Patterns in Mobile Apps,” arXiv:2411.18084, 2024. [5] Central Consumer Protection Authority, Guidelines for Prevention and Regulation of Dark Patterns, 2023. [6] A. Mathur et al., “Dark Patterns at Scale,” PACM HCI, 3(CSCW), 2019. [7] Y. Yada et al., “Dark Patterns in E-Commerce: A Dataset and Its Baseline Evaluations,” IEEE Big Data, 2022.')]

story += [PageBreak(),p('Appendix A. Point-by-Point Response to Reviewers','PaperTitle'),p('This report is appended to the revised manuscript as requested. Page references correspond to the revised PDF. Items requiring additional data, notably transformer/multimodal testing and inter-annotator agreement, are transparently identified as remaining limitations rather than presented as completed evidence.','Abs')]
responses=[('Reviewer 1 - Low novelty of TF-IDF logistic regression','Addressed on pp. 1-3. The paper now describes the classical text method as a baseline, not a novel algorithm. The main contribution is the external human-labelled Indian evaluation and the observed domain gap.'),('Reviewer 1 - Source and labels of 2,356 samples','Addressed on p. 1. The public source, four fields, class balance, provenance, and role of the benchmark corpus are specified.'),('Reviewer 1 - Transformer and existing-detector comparison','Partly addressed on pp. 1 and 3. Prior detector systems are compared as related work, with modality/task differences stated. A matched transformer experiment is not yet available and is explicitly listed as future work; no competitiveness claim is made.'),('Reviewer 1 - Implement multimodal framework','Addressed by scope correction on pp. 1-2 and 3. Figure 1 is labelled proposed. The manuscript removes performance claims for screenshot fusion or multimodal detection.'),('Reviewer 2 - Expand error analysis','Addressed on p. 2. The revision explains false-alarm reduction, low recall, and representative wording patterns behind remaining errors.'),('Reviewer 2 - Show CCPA connection','Addressed on p. 2 in Table 1. The crosswalk links pattern families, CCPA interpretations, and retained evidence, with a non-legal-advice qualifier.'),('Reviewer 2 - Cross-site generalisation','Not yet fully implemented; stated on p. 3. The present revision provides a stronger external Indian evaluation but not a leave-one-site-out protocol. This is retained as a specific next experiment.'),('Reviewer 2 - Balanced data unrealistic','Addressed on pp. 1-2. The manuscript explains why the balanced corpus cannot represent prevalence and reports low-prevalence gold-set evaluation.'),('Reviewer 2 - Per-category results','Addressed on p. 2 in Table 3. Benchmark and gold-category results are reported with explicit cautions about rare-category support.'),('Reviewer 2 - Ethical/legal issues','Addressed on p. 3. A dedicated section covers public collection, privacy, false-positive harm, human review, data sharing, and CCPA legal scope.'),('Reviewer 3 - Framework diagram','Addressed on p. 2 in Figure 1, which distinguishes completed and proposed components.'),('Reviewer 3 - Annotation agreement','Not yet available; transparently disclosed on pp. 1 and 3. The paper does not fabricate agreement and defines the double-annotation protocol required for a subsequent release.'),('Reviewer 3 - Dataset release','Addressed on p. 3. A data-availability plan defines what can be released and how restricted material will be handled.'),('Reviewer 3 - Recent literature and conclusion','Addressed on pp. 1 and 3. Related work differentiates comparable and non-comparable systems; the conclusion now reflects only validated findings.')]
for title, ans in responses:
    story += [p(title,'H2x'),p(ans)]
doc.build(story,onFirstPage=footer,onLaterPages=footer)
print(OUT.resolve())
